/*
 * basemap-data.test.js — node --test suite for the offline vector basemap files (owner: W4b basemap data).
 * assets/data/basemap/<route_id>.json are generated by tools/seed/build_basemap.py from OpenStreetMap (Overpass).
 * Checks the file format contract (PLAN "Offline vector basemap file format"), the size budget, ODbL attribution,
 * coordinates (5 decimals, inside bbox, bbox inside Vietnam) and that each file covers its pilot route network.
 * Run: node --test tools/tests/
 */
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', '..');
const DIR = path.join(ROOT, 'assets/data/basemap');
const SEED = require(path.join(ROOT, 'assets/js/data/seed-core.js'));

const ROUTES = ['khanh-le', 'ta-nang-phan-dung', 'ha-giang-loop'];
const MAX_BYTES = 700000; // per-file budget (raised from 500 000 on 2026-10-02), same as build_basemap.py MAX_BYTES
const TOP_KEYS = ['v', 'route_id', 'bbox', 'generated_at', 'source', 'license', 'attribution',
  'roads', 'water', 'places', 'peaks'];
const ROAD_CLASSES = ['trunk', 'primary', 'secondary', 'tertiary', 'unclassified', 'residential', 'track', 'path'];
const WATER_CLASSES = ['river', 'stream', 'canal', 'lake', 'reservoir'];
const PLACE_KINDS = ['town', 'village', 'hamlet', 'suburb', 'locality'];
const VN = { s: 8.0, w: 102.0, n: 23.5, e: 110.0 }; // loose envelope of mainland Vietnam

function load(id) {
  const file = path.join(DIR, id + '.json');
  return { file: file, size: fs.statSync(file).size, doc: JSON.parse(fs.readFileSync(file, 'utf8')) };
}
function isPt(p) {
  return Array.isArray(p) && p.length === 2 && typeof p[0] === 'number' && typeof p[1] === 'number' &&
    isFinite(p[0]) && isFinite(p[1]);
}
function fiveDec(v) { return Math.abs(Math.round(v * 1e5) / 1e5 - v) < 1e-9; }
function inBox(bb, p) { return p[0] >= bb[0] && p[0] <= bb[2] && p[1] >= bb[1] && p[1] <= bb[3]; }
function nameOk(n) { return n === null || (typeof n === 'string' && n.trim().length > 0); }

test('size budget matches build_basemap.py; the raw Overpass cache is git-ignored and left out of the README zip', () => {
  const py = fs.readFileSync(path.join(ROOT, 'tools/seed/build_basemap.py'), 'utf8');
  assert.equal(+/^MAX_BYTES = (\d+)/m.exec(py)[1], MAX_BYTES, 'test and builder use the same per-file limit');
  assert.ok(+/^TARGET_BYTES = (\d+)/m.exec(py)[1] < MAX_BYTES, 'the size ladder target stays under the limit');
  const ignore = fs.readFileSync(path.join(ROOT, '.gitignore'), 'utf8').split(/\r?\n/).map((l) => l.trim());
  assert.ok(ignore.indexOf('tools/seed/cache/overpass-*.json') >= 0, '.gitignore lists tools/seed/cache/overpass-*.json');
  // The folder is not a git repo, so a zip submission relies on the README command excluding the same paths.
  const zip = fs.readFileSync(path.join(ROOT, 'README.md'), 'utf8').split(/\r?\n/).filter((l) => /^zip -r /.test(l));
  assert.equal(zip.length, 1, 'README.md has one zip packaging command');
  const toZip = { 'tools/seed/cache/overpass-*.json': 'tools/seed/cache/overpass-*.json', 'mockup/node_modules/': 'mockup/node_modules/*', '.DS_Store': '*.DS_Store' };
  ignore.filter((l) => l && l[0] !== '#').forEach((l) => {
    assert.ok(toZip[l], 'zip exclusion known for .gitignore entry ' + l);
    assert.ok(zip[0].indexOf("'" + toZip[l] + "'") >= 0, 'README zip command excludes ' + toZip[l]);
  });
});

test('every pilot route has exactly one basemap file and nothing else is in the folder', () => {
  const files = fs.readdirSync(DIR).filter((f) => f.endsWith('.json')).sort();
  assert.deepEqual(files, ROUTES.map((r) => r + '.json').sort());
});

ROUTES.forEach((id) => {
  test(id + ': header, size budget and ODbL attribution', () => {
    const f = load(id);
    const d = f.doc;
    assert.ok(f.size <= MAX_BYTES, id + ' is ' + f.size + ' bytes (> ' + MAX_BYTES + ')');
    assert.deepEqual(Object.keys(d), TOP_KEYS);
    assert.equal(d.v, 1);
    assert.equal(d.route_id, id);
    assert.match(d.generated_at, /^\d{4}-\d{2}-\d{2}$/);
    assert.equal(d.source, 'OpenStreetMap (Overpass API)');
    assert.equal(d.license, 'ODbL-1.0');
    assert.equal(d.attribution, '© OpenStreetMap contributors');
    const bb = d.bbox;
    assert.ok(Array.isArray(bb) && bb.length === 4 && bb[0] < bb[2] && bb[1] < bb[3], 'bbox [s,w,n,e]');
    assert.ok(bb[0] >= VN.s && bb[2] <= VN.n && bb[1] >= VN.w && bb[3] <= VN.e, 'bbox inside Vietnam: ' + bb);
  });

  test(id + ': roads and water follow the contract', () => {
    const d = load(id).doc;
    assert.ok(d.roads.length > 100, 'roads present');
    d.roads.forEach((r, i) => {
      assert.deepEqual(Object.keys(r), ['c', 'n', 'g'], 'roads[' + i + '] keys');
      assert.ok(ROAD_CLASSES.indexOf(r.c) >= 0, 'roads[' + i + '] class ' + r.c);
      assert.ok(nameOk(r.n), 'roads[' + i + '] name');
      assert.ok(Array.isArray(r.g) && r.g.length >= 2, 'roads[' + i + '] >= 2 points');
      r.g.forEach((p) => {
        assert.ok(isPt(p) && fiveDec(p[0]) && fiveDec(p[1]) && inBox(d.bbox, p), 'roads[' + i + '] point ' + p);
      });
    });
    assert.ok(['trunk', 'primary', 'secondary', 'tertiary'].some((c) => d.roads.some((r) => r.c === c)),
      'at least one major road class');
    assert.ok(d.water.length > 10, 'water present');
    d.water.forEach((w, i) => {
      assert.deepEqual(Object.keys(w), ['c', 'n', 'a', 'g'], 'water[' + i + '] keys');
      assert.ok(WATER_CLASSES.indexOf(w.c) >= 0, 'water[' + i + '] class ' + w.c);
      assert.ok(nameOk(w.n), 'water[' + i + '] name');
      assert.equal(typeof w.a, 'boolean');
      assert.ok(w.g.length >= (w.a ? 4 : 2), 'water[' + i + '] points');
      if (w.a) assert.deepEqual(w.g[0], w.g[w.g.length - 1], 'water[' + i + '] ring closed');
      w.g.forEach((p) => {
        assert.ok(isPt(p) && fiveDec(p[0]) && fiveDec(p[1]) && inBox(d.bbox, p), 'water[' + i + '] point ' + p);
      });
    });
  });

  test(id + ': places and peaks follow the contract', () => {
    const d = load(id).doc;
    assert.ok(d.places.length >= 10, 'places present');
    d.places.forEach((p, i) => {
      assert.deepEqual(Object.keys(p), ['n', 'k', 'p'], 'places[' + i + '] keys');
      assert.ok(typeof p.n === 'string' && p.n.trim().length > 0, 'places[' + i + '] named');
      assert.ok(PLACE_KINDS.indexOf(p.k) >= 0, 'places[' + i + '] kind ' + p.k);
      assert.ok(isPt(p.p) && fiveDec(p.p[0]) && fiveDec(p.p[1]) && inBox(d.bbox, p.p), 'places[' + i + '] point');
    });
    d.peaks.forEach((p, i) => {
      assert.deepEqual(Object.keys(p), ['n', 'e', 'p'], 'peaks[' + i + '] keys');
      assert.ok(nameOk(p.n), 'peaks[' + i + '] name');
      assert.ok(p.e === null || (Number.isInteger(p.e) && p.e > -100 && p.e < 3500), 'peaks[' + i + '] ele');
      assert.ok(p.n !== null || p.e !== null, 'peaks[' + i + '] needs a name or an elevation');
      assert.ok(isPt(p.p) && fiveDec(p.p[0]) && fiveDec(p.p[1]) && inBox(d.bbox, p.p), 'peaks[' + i + '] point');
    });
  });

  test(id + ': bbox covers the whole route network of seed-core.js', () => {
    const d = load(id).doc;
    const edges = SEED.edges.filter((e) => e.route_id === id);
    assert.ok(edges.length > 0);
    edges.forEach((e) => {
      e.geometry.forEach((p) => assert.ok(inBox(d.bbox, p), e.id + ' vertex ' + p + ' outside basemap bbox'));
    });
    const nodes = SEED.nodes.filter((n) => n.route_id === id);
    nodes.forEach((n) => assert.ok(inBox(d.bbox, [n.lat, n.lng]), n.id + ' outside basemap bbox'));
  });
});
